import { describe, expect, it } from "vitest";
import {
  analyzeAgentSetupFailure,
  buildAgentSetupTroubleshootingRequest,
} from "./agentSetupTroubleshooting";
import type { ProviderDisplayInfo } from "@/shared/types/providers";

const provider: ProviderDisplayInfo = {
  id: "claude-acp",
  displayName: "Claude Code",
  category: "agent",
  description: "Claude provider",
  setupMethod: "cli_auth",
  binaryName: "claude-agent-acp",
  supportsAuth: true,
  supportsAuthStatus: true,
  supportsInstall: true,
  group: "default",
  status: "not_installed",
};

describe("agent setup troubleshooting", () => {
  it("detects an existing binary path from npm EEXIST output", () => {
    const analysis = analyzeAgentSetupFailure("Command exited with code 1", [
      { text: "npm error code EEXIST" },
      { text: "npm error path /opt/homebrew/bin/claude" },
      { text: "npm error EEXIST: file already exists" },
    ]);

    expect(analysis).toMatchObject({
      kind: "existing_file",
      existingPath: "/opt/homebrew/bin/claude",
    });
  });

  it("detects platform mismatches from npm EBADPLATFORM output", () => {
    const analysis = analyzeAgentSetupFailure("Command exited with code 1", [
      { text: "npm error code EBADPLATFORM" },
      {
        text: 'wanted {"os":"win32","cpu":"x64"} (current: {"os":"darwin","cpu":"arm64"})',
      },
    ]);

    expect(analysis).toMatchObject({
      kind: "unsupported_platform",
      wantedPlatform: "win32 / x64",
      currentPlatform: "darwin / arm64",
    });
  });

  it("builds a chat request with provider context and raw output", () => {
    const analysis = analyzeAgentSetupFailure("Command exited with code 1", [
      { text: "npm error code EEXIST" },
    ]);
    const request = buildAgentSetupTroubleshootingRequest({
      provider,
      analysis,
      userMessage: "A command already exists.",
      commandError: "Command exited with code 1",
    });

    expect(request.title).toBe("Troubleshoot Claude Code setup");
    expect(request.prompt).toContain("Provider id: claude-acp");
    expect(request.prompt).toContain("Expected CLI on PATH: claude-agent-acp");
    expect(request.prompt).toContain("npm error code EEXIST");
  });
});

import { describe, expect, it, vi } from "vitest";

import type { ModelSetupOperation } from "@/features/providers/api/modelSetup";

const mocks = vi.hoisted(() => ({
  clearModelSetupStatus: vi.fn(),
  listModelSetupStatus: vi.fn(),
  onModelSetupState: vi.fn(),
  startModelSetup: vi.fn(),
}));

vi.mock("@/features/providers/api/modelSetup", () => ({
  clearModelSetupStatus: (...args: unknown[]) =>
    mocks.clearModelSetupStatus(...args),
  listModelSetupStatus: (...args: unknown[]) =>
    mocks.listModelSetupStatus(...args),
  onModelSetupState: (...args: unknown[]) => mocks.onModelSetupState(...args),
  startModelSetup: (...args: unknown[]) => mocks.startModelSetup(...args),
}));

function makeOperation(
  overrides: Partial<ModelSetupOperation> = {},
): ModelSetupOperation {
  return {
    phase: "authenticating",
    status: "running",
    output: [],
    error: null,
    ...overrides,
  };
}

describe("useModelSetupStore", () => {
  it("does not let rehydration overwrite a listener update that arrives during the list request", async () => {
    vi.resetModules();
    vi.clearAllMocks();

    const { useModelSetupStore } = await import("./modelSetupStore");
    let emitState:
      | ((providerId: string, operation: ModelSetupOperation) => void)
      | undefined;

    const olderRunningSnapshot = makeOperation({
      status: "running",
      output: ["authenticating"],
    });
    const newerTerminalSnapshot = makeOperation({
      phase: "idle",
      status: "succeeded",
      output: ["connected"],
    });

    mocks.onModelSetupState.mockImplementation(async (callback) => {
      emitState = callback as typeof emitState;
      return vi.fn();
    });
    mocks.listModelSetupStatus.mockImplementation(async () => {
      emitState?.("databricks", newerTerminalSnapshot);
      return [["databricks", olderRunningSnapshot]];
    });

    await useModelSetupStore.getState().init();

    expect(useModelSetupStore.getState().getStatus("databricks")).toEqual(
      newerTerminalSnapshot,
    );
  });

  it("does not let a start response overwrite a listener update that arrives first", async () => {
    vi.resetModules();
    vi.clearAllMocks();

    const { useModelSetupStore } = await import("./modelSetupStore");
    let emitState:
      | ((providerId: string, operation: ModelSetupOperation) => void)
      | undefined;

    const seededRunningSnapshot = makeOperation({
      status: "running",
      output: ["authenticating"],
    });
    const newerTerminalSnapshot = makeOperation({
      phase: "idle",
      status: "succeeded",
      output: ["connected"],
    });

    mocks.onModelSetupState.mockImplementation(async (callback) => {
      emitState = callback as typeof emitState;
      return vi.fn();
    });
    mocks.listModelSetupStatus.mockResolvedValue([]);
    mocks.startModelSetup.mockImplementation(async () => {
      emitState?.("databricks", newerTerminalSnapshot);
      return seededRunningSnapshot;
    });

    await useModelSetupStore.getState().init();
    await useModelSetupStore.getState().startSetup("databricks", {
      providerLabel: "databricks",
    });

    expect(useModelSetupStore.getState().getStatus("databricks")).toEqual(
      newerTerminalSnapshot,
    );
  });
});

import { describe, expect, it, vi } from "vitest";

import type { AgentSetupOperation } from "@/features/providers/api/agentSetup";

const mocks = vi.hoisted(() => ({
  clearAgentSetupStatus: vi.fn(),
  listAgentSetupStatus: vi.fn(),
  onAgentSetupState: vi.fn(),
  startAgentSetup: vi.fn(),
}));

vi.mock("@/features/providers/api/agentSetup", () => ({
  clearAgentSetupStatus: (...args: unknown[]) =>
    mocks.clearAgentSetupStatus(...args),
  listAgentSetupStatus: (...args: unknown[]) =>
    mocks.listAgentSetupStatus(...args),
  onAgentSetupState: (...args: unknown[]) => mocks.onAgentSetupState(...args),
  startAgentSetup: (...args: unknown[]) => mocks.startAgentSetup(...args),
}));

function makeOperation(
  overrides: Partial<AgentSetupOperation> = {},
): AgentSetupOperation {
  return {
    action: "install",
    phase: "installing",
    status: "running",
    output: [],
    error: null,
    ...overrides,
  };
}

describe("useAgentSetupStore", () => {
  it("does not let rehydration overwrite a listener update that arrives during the list request", async () => {
    vi.resetModules();
    vi.clearAllMocks();

    const { useAgentSetupStore } = await import("./agentSetupStore");
    let emitState:
      | ((providerId: string, operation: AgentSetupOperation) => void)
      | undefined;

    const olderRunningSnapshot = makeOperation({
      status: "running",
      output: ["installing"],
    });
    const newerTerminalSnapshot = makeOperation({
      phase: "checking",
      status: "succeeded",
      output: ["installed"],
    });

    mocks.onAgentSetupState.mockImplementation(async (callback) => {
      emitState = callback as typeof emitState;
      return vi.fn();
    });
    mocks.listAgentSetupStatus.mockImplementation(async () => {
      emitState?.("claude-acp", newerTerminalSnapshot);
      return [["claude-acp", olderRunningSnapshot]];
    });

    await useAgentSetupStore.getState().init();

    expect(useAgentSetupStore.getState().getStatus("claude-acp")).toEqual(
      newerTerminalSnapshot,
    );
  });

  it("does not let a start response overwrite a listener update that arrives first", async () => {
    vi.resetModules();
    vi.clearAllMocks();

    const { useAgentSetupStore } = await import("./agentSetupStore");
    let emitState:
      | ((providerId: string, operation: AgentSetupOperation) => void)
      | undefined;

    const seededRunningSnapshot = makeOperation({
      status: "running",
      output: ["installing"],
    });
    const newerTerminalSnapshot = makeOperation({
      phase: "checking",
      status: "succeeded",
      output: ["installed"],
    });

    mocks.onAgentSetupState.mockImplementation(async (callback) => {
      emitState = callback as typeof emitState;
      return vi.fn();
    });
    mocks.listAgentSetupStatus.mockResolvedValue([]);
    mocks.startAgentSetup.mockImplementation(async () => {
      emitState?.("claude-acp", newerTerminalSnapshot);
      return seededRunningSnapshot;
    });

    await useAgentSetupStore.getState().init();
    await useAgentSetupStore.getState().startSetup("claude-acp", "install", {
      installFixType: "command",
      updateFixTypes: [],
      verifyInstall: true,
    });

    expect(useAgentSetupStore.getState().getStatus("claude-acp")).toEqual(
      newerTerminalSnapshot,
    );
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";
import { invoke } from "@tauri-apps/api/core";
import {
  getInstallationCohort,
  INSTALLATION_COHORT_TIMEOUT_MS,
} from "./installationCohort";

vi.mock("@tauri-apps/api/core", () => ({ invoke: vi.fn() }));

describe("getInstallationCohort", () => {
  afterEach(() => {
    vi.useRealTimers();
    vi.clearAllMocks();
  });

  it("rejects a stalled lookup after the deadline", async () => {
    vi.useFakeTimers();
    vi.mocked(invoke).mockReturnValue(new Promise(() => {}));
    const result = expect(getInstallationCohort()).rejects.toThrow("timed out");

    await vi.advanceTimersByTimeAsync(INSTALLATION_COHORT_TIMEOUT_MS);

    await result;
  });
});

import { beforeEach, describe, expect, it, vi } from "vitest";
import {
  getMicrophonePermissionStatus,
  openMicrophonePrivacySettings,
} from "./microphonePermission";

const mocks = vi.hoisted(() => ({ invoke: vi.fn() }));

vi.mock("@tauri-apps/api/core", () => ({ invoke: mocks.invoke }));

describe("microphone permission API", () => {
  beforeEach(() => mocks.invoke.mockReset());

  it("uses the native status and settings commands", async () => {
    mocks.invoke
      .mockResolvedValueOnce("notDetermined")
      .mockResolvedValueOnce(undefined);

    await expect(getMicrophonePermissionStatus()).resolves.toBe(
      "notDetermined",
    );
    await expect(openMicrophonePrivacySettings()).resolves.toBeUndefined();

    expect(mocks.invoke).toHaveBeenNthCalledWith(
      1,
      "get_microphone_permission_status",
    );
    expect(mocks.invoke).toHaveBeenNthCalledWith(
      2,
      "open_microphone_privacy_settings",
    );
  });
});

import { waitFor } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import type { ModelOption } from "@/features/chat/types";
import {
  DEFAULT_RUNTIME_CONFIG,
  type RuntimeConfig,
} from "@/shared/runtime-config/schema";
import { useRuntimeConfigStore } from "@/shared/runtime-config/runtimeConfigStore";
import { useProviderModelCacheStore } from "./providerModelCacheStore";

const mocks = vi.hoisted(() => ({
  getClient: vi.fn(),
  supportedModelsList: vi.fn(),
}));

vi.mock("@/shared/api/acpConnection", () => ({
  getClient: () => mocks.getClient(),
}));

function seededModel(overrides: Partial<ModelOption> = {}): ModelOption {
  return {
    id: "seeded-model",
    name: "Seeded model",
    displayName: "Seeded model",
    providerId: "databricks_v2",
    providerName: "Databricks",
    recommended: false,
    featured: false,
    ...overrides,
  };
}

describe("providerModelCacheStore", () => {
  beforeEach(() => {
    vi.resetAllMocks();
    window.localStorage.clear();
    useProviderModelCacheStore.setState({
      providers: new Map(),
      refreshingProviderIds: new Set(),
      runtimeManagedProviderIds: new Set(),
    });
    useRuntimeConfigStore.setState({ config: DEFAULT_RUNTIME_CONFIG });
    mocks.getClient.mockResolvedValue({
      goose: {
        GooseUnstableProvidersSupportedModelsList: mocks.supportedModelsList,
      },
    });
  });

  it("seeds runtime models as authoritative runtime-managed entries", async () => {
    const model = seededModel({
      contextLimit: 128000,
      recommended: true,
      featured: true,
      sortOrder: 0,
    });

    useProviderModelCacheStore
      .getState()
      .seedRuntimeModels(new Map([["databricks_v2", [model]]]));
    await useProviderModelCacheStore
      .getState()
      .refreshAllModelProviders(["databricks_v2"]);
    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("databricks_v2", { force: true });

    const entry = useProviderModelCacheStore
      .getState()
      .providers.get("databricks_v2");
    expect(entry?.runtimeManaged).toBe(true);
    expect(
      useProviderModelCacheStore
        .getState()
        .getModelsForProvider("databricks_v2"),
    ).toEqual([model]);
    expect(mocks.supportedModelsList).not.toHaveBeenCalled();
  });

  it("preserves runtime-managed models after invalidation and forced refresh", async () => {
    const model = seededModel({
      contextLimit: 128000,
      recommended: true,
      featured: true,
      sortOrder: 0,
    });

    useProviderModelCacheStore
      .getState()
      .seedRuntimeModels(new Map([["databricks_v2", [model]]]));
    useProviderModelCacheStore.getState().invalidateProvider("databricks_v2");

    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("databricks_v2", { force: true });

    const entry = useProviderModelCacheStore
      .getState()
      .providers.get("databricks_v2");
    expect(entry?.runtimeManaged).toBe(true);
    expect(
      useProviderModelCacheStore
        .getState()
        .getModelsForProvider("databricks_v2"),
    ).toEqual([model]);
    expect(mocks.supportedModelsList).not.toHaveBeenCalled();
  });

  it("keeps refreshable runtime models provisional until discovery succeeds", async () => {
    const configuredModel = seededModel({ id: "goose-gpt-5-5" });
    useProviderModelCacheStore
      .getState()
      .seedRuntimeModels(new Map([["databricks_v2", [configuredModel]]]), {
        runtimeManagedProviderIds: new Set(),
      });

    expect(
      useProviderModelCacheStore
        .getState()
        .isModelInventoryAuthoritative("databricks_v2"),
    ).toBe(false);

    mocks.supportedModelsList.mockResolvedValueOnce({
      models: ["goose-gpt-5-5", "goose-claude-fable"],
    });
    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("databricks_v2");

    expect(
      useProviderModelCacheStore
        .getState()
        .isModelInventoryAuthoritative("databricks_v2"),
    ).toBe(true);
  });

  it.each([
    {
      label: "stale",
      fetchedAt: 1,
      force: false,
      error: undefined,
    },
    {
      label: "fresh forced with an error",
      fetchedAt: Date.now(),
      force: true,
      error: "authentication failed",
    },
    {
      label: "retryable with an error",
      fetchedAt: 0,
      force: false,
      error: "authentication failed",
    },
  ])("preserves a $label populated cache and retries after empty discovery", async ({
    fetchedAt,
    force,
    error,
  }) => {
    const cachedEntry = {
      providerId: "openrouter",
      models: [
        seededModel({
          providerId: "openrouter",
          providerName: "OpenRouter",
        }),
      ],
      fetchedAt,
      ...(error ? { error } : {}),
    };
    window.localStorage.setItem(
      "goose:providerModelCache:v2",
      JSON.stringify([cachedEntry]),
    );
    useProviderModelCacheStore.getState().loadPersisted();
    mocks.supportedModelsList
      .mockResolvedValueOnce({ models: [] })
      .mockResolvedValueOnce({ models: ["replacement-model"] });

    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("openrouter", { force });

    const retryableEntry = { ...cachedEntry, fetchedAt: 0 };
    delete retryableEntry.error;
    expect(
      useProviderModelCacheStore.getState().providers.get("openrouter"),
    ).toEqual(retryableEntry);
    expect(
      JSON.parse(
        window.localStorage.getItem("goose:providerModelCache:v2") ?? "[]",
      ),
    ).toEqual([retryableEntry]);
    expect(useProviderModelCacheStore.getState().getError("openrouter")).toBe(
      null,
    );

    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("openrouter");

    expect(mocks.supportedModelsList).toHaveBeenCalledTimes(2);
    expect(
      useProviderModelCacheStore
        .getState()
        .getModelsForProvider("openrouter")
        .map((model) => model.id),
    ).toEqual(["replacement-model"]);
  });

  it("keeps configured models provisional and retryable after empty discovery", async () => {
    const configuredModel = seededModel({
      providerId: "openrouter",
      providerName: "OpenRouter",
    });
    useProviderModelCacheStore
      .getState()
      .seedRuntimeModels(new Map([["openrouter", [configuredModel]]]), {
        runtimeManagedProviderIds: new Set(),
      });
    mocks.supportedModelsList
      .mockResolvedValueOnce({ models: [] })
      .mockResolvedValueOnce({ models: ["discovered-model"] });

    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("openrouter");

    const provisionalEntry = useProviderModelCacheStore
      .getState()
      .providers.get("openrouter");
    expect(provisionalEntry).toEqual({
      providerId: "openrouter",
      models: [configuredModel],
      configuredModels: [configuredModel],
      fetchedAt: 0,
    });
    expect(
      useProviderModelCacheStore
        .getState()
        .isModelInventoryAuthoritative("openrouter"),
    ).toBe(false);

    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("openrouter");

    expect(mocks.supportedModelsList).toHaveBeenCalledTimes(2);
    expect(
      useProviderModelCacheStore
        .getState()
        .getModelsForProvider("openrouter")
        .map((model) => model.id),
    ).toEqual(["discovered-model", configuredModel.id]);
  });

  it("retries after an empty refresh with no cached entry", async () => {
    mocks.supportedModelsList
      .mockResolvedValueOnce({ models: [] })
      .mockResolvedValueOnce({ models: ["openrouter-model"] });

    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("openrouter");
    expect(
      useProviderModelCacheStore.getState().providers.has("openrouter"),
    ).toBe(false);

    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("openrouter");

    expect(mocks.supportedModelsList).toHaveBeenCalledTimes(2);
    expect(
      useProviderModelCacheStore
        .getState()
        .getModelsForProvider("openrouter")
        .map((model) => model.id),
    ).toEqual(["openrouter-model"]);
  });

  it("ignores legacy fresh-empty cache entries", async () => {
    window.localStorage.setItem(
      "goose:providerModelCache:v1",
      JSON.stringify([
        {
          providerId: "openrouter",
          models: [],
          fetchedAt: Date.now(),
        },
      ]),
    );
    useProviderModelCacheStore.getState().loadPersisted();
    expect(
      useProviderModelCacheStore
        .getState()
        .isModelInventoryAuthoritative("openrouter"),
    ).toBe(false);
    mocks.supportedModelsList
      .mockResolvedValueOnce({ models: [] })
      .mockResolvedValueOnce({ models: ["openrouter-model"] });

    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("openrouter");

    expect(
      useProviderModelCacheStore
        .getState()
        .isModelInventoryAuthoritative("openrouter"),
    ).toBe(false);

    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("openrouter");

    expect(mocks.supportedModelsList).toHaveBeenCalledTimes(2);
    expect(
      useProviderModelCacheStore
        .getState()
        .getModelsForProvider("openrouter")
        .map((model) => model.id),
    ).toEqual(["openrouter-model"]);
  });

  it("applies the runtime model id prefix allowlist to discovery", async () => {
    const config: RuntimeConfig = {
      schemaVersion: 1,
      goose: {
        defaultModelProviderId: "databricks_v2",
        modelProviders: [
          {
            id: "databricks_v2",
            displayName: "Databricks",
            allowedModelIdPrefixes: ["goose-", "team.approved."],
            models: [],
          },
        ],
      },
    };
    useRuntimeConfigStore.setState({ config });
    mocks.supportedModelsList.mockResolvedValueOnce({
      models: [
        "goose-gpt-5-5",
        "team.approved.chat-model",
        "other.schema.chat-model",
      ],
    });

    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("databricks_v2");

    expect(
      useProviderModelCacheStore
        .getState()
        .getModelsForProvider("databricks_v2")
        .map((model) => model.id),
    ).toEqual(["goose-gpt-5-5", "team.approved.chat-model"]);
  });

  it("caches a successful inventory when every discovered model is filtered", async () => {
    const config: RuntimeConfig = {
      schemaVersion: 1,
      goose: {
        defaultModelProviderId: "databricks_v2",
        modelProviders: [
          {
            id: "databricks_v2",
            displayName: "Databricks",
            allowedModelIdPrefixes: ["goose-"],
            models: [],
          },
        ],
      },
    };
    useRuntimeConfigStore.setState({ config });
    mocks.supportedModelsList.mockResolvedValue({
      models: ["other.schema.chat-model"],
    });

    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("databricks_v2");
    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("databricks_v2");

    expect(mocks.supportedModelsList).toHaveBeenCalledTimes(1);
    expect(
      useProviderModelCacheStore
        .getState()
        .isModelInventoryAuthoritative("databricks_v2"),
    ).toBe(true);
    expect(
      useProviderModelCacheStore
        .getState()
        .getModelsForProvider("databricks_v2"),
    ).toEqual([]);
  });

  it("preserves bundled metadata while refreshing the available model list", async () => {
    const configuredModel = seededModel({
      id: "goose-gpt-5-6-sol",
      name: "GPT-5.6 Sol",
      displayName: "GPT-5.6 Sol",
      recommended: true,
      featured: true,
    });
    useProviderModelCacheStore
      .getState()
      .seedRuntimeModels(new Map([["databricks_v2", [configuredModel]]]), {
        runtimeManagedProviderIds: new Set(),
      });
    mocks.supportedModelsList.mockResolvedValueOnce({
      models: ["goose-gpt-5-5", "goose-gpt-5-6-sol", "goose-claude-opus-4"],
    });

    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("databricks_v2");

    expect(mocks.supportedModelsList).toHaveBeenCalledWith({
      providerId: "databricks_v2",
    });
    const models = useProviderModelCacheStore
      .getState()
      .getModelsForProvider("databricks_v2");
    expect(models).toHaveLength(3);
    expect(models.find((model) => model.id === "goose-gpt-5-5")).toEqual(
      expect.objectContaining({
        id: "goose-gpt-5-5",
        recommended: true,
        featured: false,
      }),
    );
    expect(models.find((model) => model.id === "goose-gpt-5-6-sol")).toEqual(
      expect.objectContaining(configuredModel),
    );
    expect(models.find((model) => model.id === "goose-claude-opus-4")).toEqual(
      expect.objectContaining({
        id: "goose-claude-opus-4",
        recommended: true,
        featured: false,
      }),
    );
  });

  it("keeps configured models that are missing from the provider model list", async () => {
    const configuredModel = seededModel({
      id: "goose-gpt-5-6-sol",
      name: "GPT-5.6 Sol",
      displayName: "GPT-5.6 Sol",
      recommended: true,
      featured: true,
    });
    useProviderModelCacheStore
      .getState()
      .seedRuntimeModels(new Map([["databricks_v2", [configuredModel]]]), {
        runtimeManagedProviderIds: new Set(),
      });
    mocks.supportedModelsList.mockResolvedValueOnce({
      models: ["goose-gpt-5-5"],
    });

    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("databricks_v2");

    const models = useProviderModelCacheStore
      .getState()
      .getModelsForProvider("databricks_v2");
    expect(models.map((model) => model.id)).toEqual([
      "goose-gpt-5-5",
      "goose-gpt-5-6-sol",
    ]);
    expect(models.find((model) => model.id === "goose-gpt-5-6-sol")).toEqual(
      expect.objectContaining(configuredModel),
    );
  });

  it("keeps configured models after a failed refresh and retry", async () => {
    const configuredModel = seededModel({
      id: "goose-gpt-5-6-sol",
      name: "GPT-5.6 Sol",
      displayName: "GPT-5.6 Sol",
      recommended: true,
    });
    useProviderModelCacheStore
      .getState()
      .seedRuntimeModels(new Map([["databricks_v2", [configuredModel]]]), {
        runtimeManagedProviderIds: new Set(),
      });
    mocks.supportedModelsList
      .mockRejectedValueOnce(new Error("not authenticated"))
      .mockResolvedValueOnce({ models: ["goose-gpt-5-5"] });

    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("databricks_v2");
    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("databricks_v2", { force: true });

    expect(
      useProviderModelCacheStore
        .getState()
        .getModelsForProvider("databricks_v2")
        .map((model) => model.id),
    ).toEqual(["goose-gpt-5-5", "goose-gpt-5-6-sol"]);
  });

  it("removes stale runtime-managed providers when runtime config changes", () => {
    const model = seededModel();

    useProviderModelCacheStore.getState().seedRuntimeModels(
      new Map([
        ["databricks_v2", [model]],
        [
          "block_openai_compatible",
          [
            {
              ...model,
              providerId: "block_openai_compatible",
              providerName: "Block AI Gateway",
            },
          ],
        ],
      ]),
    );
    useProviderModelCacheStore
      .getState()
      .seedRuntimeModels(new Map([["databricks_v2", [model]]]));

    expect(
      useProviderModelCacheStore
        .getState()
        .providers.has("block_openai_compatible"),
    ).toBe(false);
    expect(
      useProviderModelCacheStore.getState().providers.has("databricks_v2"),
    ).toBe(true);
  });

  it("runs a forced refresh after an in-flight refresh finishes", async () => {
    let rejectInitialRefresh!: (error: Error) => void;
    const initialRefresh = new Promise<{ models: string[] }>(
      (_resolve, reject) => {
        rejectInitialRefresh = reject;
      },
    );
    mocks.supportedModelsList
      .mockReturnValueOnce(initialRefresh)
      .mockResolvedValueOnce({
        models: ["goose-gpt-5-5"],
      });

    const firstRefreshPromise = useProviderModelCacheStore
      .getState()
      .refreshProviderModels("databricks_v2");

    await waitFor(() =>
      expect(mocks.supportedModelsList).toHaveBeenCalledTimes(1),
    );

    const forcedRefreshPromise = useProviderModelCacheStore
      .getState()
      .refreshProviderModels("databricks_v2", { force: true });

    rejectInitialRefresh(new Error("not authenticated"));

    await Promise.all([firstRefreshPromise, forcedRefreshPromise]);

    expect(mocks.supportedModelsList).toHaveBeenCalledTimes(2);
    expect(
      useProviderModelCacheStore
        .getState()
        .getModelsForProvider("databricks_v2")
        .map((model) => model.id),
    ).toEqual(["goose-gpt-5-5"]);
    expect(
      useProviderModelCacheStore.getState().getError("databricks_v2"),
    ).toBe(null);
  });

  it("does not write stale refresh results after invalidation", async () => {
    let resolveInitialRefresh!: (value: { models: string[] }) => void;
    const initialRefresh = new Promise<{ models: string[] }>((resolve) => {
      resolveInitialRefresh = resolve;
    });
    mocks.supportedModelsList.mockReturnValueOnce(initialRefresh);

    const refreshPromise = useProviderModelCacheStore
      .getState()
      .refreshProviderModels("databricks_v2");

    await waitFor(() =>
      expect(mocks.supportedModelsList).toHaveBeenCalledTimes(1),
    );

    useProviderModelCacheStore.getState().invalidateProvider("databricks_v2");
    resolveInitialRefresh({ models: ["goose-gpt-5-5"] });
    await refreshPromise;

    expect(
      useProviderModelCacheStore
        .getState()
        .getModelsForProvider("databricks_v2"),
    ).toEqual([]);
  });

  it("stores ACP error data when supported model refresh fails", async () => {
    const error = new Error("Internal error") as Error & { data: string };
    error.name = "RequestError";
    error.data =
      "Failed to fetch provider supported models: Databricks token expired";
    mocks.supportedModelsList.mockRejectedValueOnce(error);

    await useProviderModelCacheStore
      .getState()
      .refreshProviderModels("databricks_v2");

    expect(
      useProviderModelCacheStore.getState().getError("databricks_v2"),
    ).toBe(
      "Failed to fetch provider supported models: Databricks token expired",
    );
  });
});

import * as React from "react";

import { cn } from "@/shared/lib/cn";
import { Button, type ButtonProps } from "@/shared/ui/button";

/**
 * Chrome button for actions inside the chat composer surface.
 *
 * Composes Button. Base semantic variant: `subtle`.
 *
 * Extra styling on top of subtle:
 * - fill uses the composer surface tokens (`--surface-composer-action`,
 *   gray-300-family) instead of `accent` — the composer's glass surface
 *   needs a stronger fill than content surfaces
 * - hover/active/open states step through the composer action tokens
 *   (`-hover`, `-active`) instead of `accent-hover`
 * - label pins to `foreground` in every state
 *
 * Use only for controls that sit on the composer pill / chat input surface.
 * On ordinary content surfaces, use `Button variant="subtle"`.
 *
 * Intent: the recipe owns every interactive state so composer chrome can
 * never drift when the base variant changes. The base `subtle` contributes
 * role, geometry, focus behavior, and icon sizing, not colors. No flag
 * props are used or accepted.
 */
const COMPOSER_ACTION_RECIPE =
  "bg-surface-composer-action text-foreground shadow-none hover:bg-surface-composer-action-hover hover:text-foreground active:bg-surface-composer-action-active active:text-foreground data-[state=open]:bg-surface-composer-action-hover data-[state=open]:text-foreground aria-expanded:bg-surface-composer-action-hover aria-expanded:text-foreground";
const COMPOSER_ACTION_FEEDBACK_RECIPE = {
  active:
    "bg-info text-info-foreground hover:bg-info/90 hover:text-info-foreground active:bg-info/90 active:text-info-foreground",
  error:
    "bg-destructive text-destructive-foreground hover:bg-destructive/90 hover:text-destructive-foreground active:bg-destructive/90 active:text-destructive-foreground",
  destructive:
    "bg-destructive text-destructive-foreground hover:bg-destructive/90 hover:text-destructive-foreground active:bg-destructive/90 active:text-destructive-foreground",
} as const;

export type ComposerActionVisualState =
  keyof typeof COMPOSER_ACTION_FEEDBACK_RECIPE;

export type ComposerActionButtonProps = Omit<
  ButtonProps,
  "variant" | "flush" | "destructive"
> & {
  visualState?: ComposerActionVisualState;
};

export const ComposerActionButton = React.forwardRef<
  HTMLButtonElement,
  ComposerActionButtonProps
>(({ className, visualState, ...props }, ref) => (
  <Button
    ref={ref}
    variant="subtle"
    className={cn(
      COMPOSER_ACTION_RECIPE,
      visualState && COMPOSER_ACTION_FEEDBACK_RECIPE[visualState],
      visualState === "active" && "animate-pulse motion-reduce:animate-none",
      className,
    )}
    {...props}
  />
));
ComposerActionButton.displayName = "ComposerActionButton";

