//! Safe local lifecycle for marketplace-managed Agent Markdown documents.

#![allow(dead_code)]

use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use serde_yaml::Value as YamlValue;

use super::agents_models::{AgentInstallResolution, InstalledAgentRequest};
use super::skills_api::{exit_codes, failure, MarketplaceClient};
use super::skills_archive::{extract_zip_safely, sha256_hex, verify_agent_artifact};
use super::skills_config::{default_agents_agents_dir, kgoose_service_url, SkillsConfig};
use super::skills_targets::iso8601_utc;

const RECORD_SCHEMA: &str = "bb-agent-install/v1";
const LOCK_STALE_SECS: u64 = 15 * 60;

#[derive(Debug, Clone)]
pub struct AgentPaths {
    pub target: PathBuf,
    pub state: PathBuf,
    lock: PathBuf,
}

pub fn validate_slug(slug: &str) -> Result<()> {
    if slug.is_empty()
        || !slug.bytes().all(|byte| {
            byte.is_ascii_lowercase() || byte.is_ascii_digit() || matches!(byte, b'-' | b'_')
        })
    {
        return Err(failure(
            exit_codes::FS_CONFLICT,
            "invalid_agent_slug",
            format!("invalid agent slug `{slug}`"),
        ));
    }
    Ok(())
}

pub fn agent_paths(config: &SkillsConfig, slug: &str) -> Result<AgentPaths> {
    validate_slug(slug)?;
    let agents_root = if config.local_dev {
        config.skills_home.join("agents")
    } else {
        default_agents_agents_dir()
    };
    let state_root = config.bb_home.join("agents").join("installed");
    Ok(AgentPaths {
        target: agents_root.join(format!("{slug}.md")),
        state: state_root.join(format!("{slug}.json")),
        lock: config
            .bb_home
            .join("agents")
            .join("locks")
            .join(format!("{slug}.lock")),
    })
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct InstalledAgentMetadata {
    pub schema_version: String,
    pub kind: String,
    pub slug: String,
    pub version_id: String,
    pub content_sha256: String,
    pub installed_file_sha256: String,
    pub artifact_id: String,
    pub artifact_sha256: String,
    pub artifact_size_bytes: u64,
    pub artifact_media_type: String,
    pub source_id: String,
    pub source_snapshot_id: String,
    pub source_revision: String,
    pub source_path: String,
    pub server_url: String,
    pub installed_at: String,
    pub installed_via: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AgentOwnership {
    Absent,
    ManagedExact(InstalledAgentMetadata),
    ManagedMissingFile(InstalledAgentMetadata),
    ProtectedConflict { reason: String },
}

pub fn classify(paths: &AgentPaths, slug: &str) -> Result<AgentOwnership> {
    validate_slug(slug)?;
    let target = fs::symlink_metadata(&paths.target);
    let state = fs::symlink_metadata(&paths.state);
    match (target, state) {
        (Err(target_err), Err(state_err))
            if target_err.kind() == std::io::ErrorKind::NotFound
                && state_err.kind() == std::io::ErrorKind::NotFound =>
        {
            Ok(AgentOwnership::Absent)
        }
        (target, state) => {
            let metadata = match state {
                Ok(metadata) if metadata.file_type().is_file() => read_metadata(&paths.state),
                Ok(_) => Err(anyhow::anyhow!("state path is not a regular file")),
                Err(err) => Err(anyhow::Error::new(err)),
            };
            let metadata = match metadata {
                Ok(metadata)
                    if metadata.schema_version == RECORD_SCHEMA
                        && metadata.kind == "agent"
                        && metadata.slug == slug =>
                {
                    metadata
                }
                Ok(_) => {
                    return Ok(AgentOwnership::ProtectedConflict {
                        reason: "state record does not prove ownership of this agent".to_string(),
                    })
                }
                Err(_) => {
                    return Ok(AgentOwnership::ProtectedConflict {
                        reason: "state record is missing, malformed, or not a regular file"
                            .to_string(),
                    })
                }
            };
            match target {
                Err(err) if err.kind() == std::io::ErrorKind::NotFound => {
                    Ok(AgentOwnership::ManagedMissingFile(metadata))
                }
                Ok(file) if file.file_type().is_file() => {
                    let bytes = fs::read(&paths.target)
                        .with_context(|| format!("read {}", paths.target.display()))?;
                    if sha256_hex(&bytes) == metadata.installed_file_sha256 {
                        Ok(AgentOwnership::ManagedExact(metadata))
                    } else {
                        Ok(AgentOwnership::ProtectedConflict {
                            reason: "agent file differs from its managed record".to_string(),
                        })
                    }
                }
                _ => Ok(AgentOwnership::ProtectedConflict {
                    reason: "agent target is not a regular managed file".to_string(),
                }),
            }
        }
    }
}

pub fn installed_request(ownership: &AgentOwnership) -> Vec<InstalledAgentRequest> {
    match ownership {
        AgentOwnership::ManagedExact(metadata) => vec![InstalledAgentRequest {
            slug: metadata.slug.clone(),
            version_id: Some(metadata.version_id.clone()),
            content_sha256: Some(metadata.content_sha256.clone()),
            scope: Some("global".to_string()),
            targets: Vec::new(),
            installed_via: Some(metadata.installed_via.clone()),
            local_source: false,
        }],
        _ => Vec::new(),
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AgentLifecycleStatus {
    Installed,
    Updated,
    UpToDate,
    Removed,
    AlreadyAbsent,
    Conflict,
}

#[derive(Debug, Clone)]
pub struct AgentLifecycleResult {
    pub status: AgentLifecycleStatus,
    pub slug: String,
    pub path: PathBuf,
    pub metadata: Option<InstalledAgentMetadata>,
    pub reason: Option<String>,
}

pub fn install_or_update(
    config: &SkillsConfig,
    client: &MarketplaceClient,
    slug: &str,
    version_id: Option<String>,
) -> Result<AgentLifecycleResult> {
    apply_install_or_update(config, client, slug, version_id, false)
}

pub fn update(
    config: &SkillsConfig,
    client: &MarketplaceClient,
    slug: &str,
    version_id: Option<String>,
) -> Result<AgentLifecycleResult> {
    apply_install_or_update(config, client, slug, version_id, true)
}

fn apply_install_or_update(
    config: &SkillsConfig,
    client: &MarketplaceClient,
    slug: &str,
    version_id: Option<String>,
    update_only: bool,
) -> Result<AgentLifecycleResult> {
    let paths = agent_paths(config, slug)?;
    let _lock = AgentLock::acquire(&paths.lock)?;
    let ownership = classify(&paths, slug)?;
    if update_only && matches!(&ownership, AgentOwnership::Absent) {
        return Err(failure(
            exit_codes::GENERAL,
            "not_installed",
            format!("agent `{slug}` is not installed; run `bb agents install {slug}`"),
        ));
    }
    if let AgentOwnership::ProtectedConflict { reason } = ownership {
        return Ok(conflict_result(slug, &paths, reason));
    }
    let resolution =
        client
            .agents()
            .resolve_install(slug, version_id, installed_request(&ownership))?;
    let document = download_if_required(&ownership, &resolution.action, || {
        download_agent_document(client, &resolution)
    })?;
    if document.is_none() {
        let AgentOwnership::ManagedExact(metadata) = ownership else {
            unreachable!()
        };
        return Ok(up_to_date_result(slug, &paths, metadata, resolution.reason));
    }
    let document = document.expect("agent download is required for a non-noop operation");
    let metadata = metadata_for(config, &resolution, slug, &document)?;
    replace_pair(&paths, &document, &metadata)?;
    Ok(AgentLifecycleResult {
        status: if matches!(
            ownership,
            AgentOwnership::Absent | AgentOwnership::ManagedMissingFile(_)
        ) {
            AgentLifecycleStatus::Installed
        } else {
            AgentLifecycleStatus::Updated
        },
        slug: slug.to_string(),
        path: paths.target,
        metadata: Some(metadata),
        reason: Some(resolution.reason),
    })
}

pub fn remove(config: &SkillsConfig, slug: &str) -> Result<AgentLifecycleResult> {
    let paths = agent_paths(config, slug)?;
    let _lock = AgentLock::acquire(&paths.lock)?;
    remove_at_paths(&paths, slug)
}

fn remove_at_paths(paths: &AgentPaths, slug: &str) -> Result<AgentLifecycleResult> {
    match classify(paths, slug)? {
        AgentOwnership::Absent => Ok(AgentLifecycleResult {
            status: AgentLifecycleStatus::AlreadyAbsent,
            slug: slug.to_string(),
            path: paths.target.clone(),
            metadata: None,
            reason: None,
        }),
        AgentOwnership::ProtectedConflict { reason } => Ok(conflict_result(slug, paths, reason)),
        AgentOwnership::ManagedExact(metadata) => {
            remove_pair(paths, true)?;
            Ok(removed_result(slug, paths.target.clone(), metadata))
        }
        AgentOwnership::ManagedMissingFile(metadata) => {
            remove_pair(paths, false)?;
            Ok(removed_result(slug, paths.target.clone(), metadata))
        }
    }
}

fn conflict_result(slug: &str, paths: &AgentPaths, reason: String) -> AgentLifecycleResult {
    AgentLifecycleResult {
        status: AgentLifecycleStatus::Conflict,
        slug: slug.to_string(),
        path: paths.target.clone(),
        metadata: None,
        reason: Some(reason),
    }
}

fn removed_result(
    slug: &str,
    path: PathBuf,
    metadata: InstalledAgentMetadata,
) -> AgentLifecycleResult {
    AgentLifecycleResult {
        status: AgentLifecycleStatus::Removed,
        slug: slug.to_string(),
        path,
        metadata: Some(metadata),
        reason: None,
    }
}

fn up_to_date_result(
    slug: &str,
    paths: &AgentPaths,
    metadata: InstalledAgentMetadata,
    reason: String,
) -> AgentLifecycleResult {
    AgentLifecycleResult {
        status: AgentLifecycleStatus::UpToDate,
        slug: slug.to_string(),
        path: paths.target.clone(),
        metadata: Some(metadata),
        reason: Some(reason),
    }
}

fn download_if_required<F>(
    ownership: &AgentOwnership,
    action: &str,
    download: F,
) -> Result<Option<Vec<u8>>>
where
    F: FnOnce() -> Result<Vec<u8>>,
{
    if action == "noop" && matches!(ownership, AgentOwnership::ManagedExact(_)) {
        Ok(None)
    } else {
        download().map(Some)
    }
}

fn read_metadata(path: &Path) -> Result<InstalledAgentMetadata> {
    serde_json::from_slice(&fs::read(path).with_context(|| format!("read {}", path.display()))?)
        .with_context(|| format!("parse {}", path.display()))
}

fn download_agent_document(
    client: &MarketplaceClient,
    resolution: &AgentInstallResolution,
) -> Result<Vec<u8>> {
    let artifact = resolution
        .artifact
        .as_ref()
        .context("agent install operation did not include artifact metadata")?;
    let download = client.download(&artifact.download_url)?;
    verify_agent_artifact(&download, artifact)?;
    let parent = std::env::temp_dir().join(format!(
        "bb-agent-validate-{}-{}",
        resolution.plan.slug,
        unique_suffix()
    ));
    fs::create_dir_all(&parent).with_context(|| format!("create {}", parent.display()))?;
    let result = (|| {
        extract_zip_safely(&download.bytes, &parent)?;
        read_agent_document(&parent)
    })();
    let _ = fs::remove_dir_all(&parent);
    result
}

fn read_agent_document(root: &Path) -> Result<Vec<u8>> {
    let mut candidates = Vec::new();
    collect_markdown(root, &mut candidates)?;
    if candidates.len() != 1 {
        anyhow::bail!(
            "agent artifact must contain exactly one Agent Markdown document; found {}",
            candidates.len()
        );
    }
    let bytes =
        fs::read(&candidates[0]).with_context(|| format!("read {}", candidates[0].display()))?;
    validate_agent_document(&bytes)?;
    Ok(bytes)
}

fn collect_markdown(root: &Path, candidates: &mut Vec<PathBuf>) -> Result<()> {
    for entry in fs::read_dir(root).with_context(|| format!("read {}", root.display()))? {
        let entry = entry.with_context(|| format!("read entry in {}", root.display()))?;
        let file_type = entry
            .file_type()
            .with_context(|| format!("stat {}", entry.path().display()))?;
        if file_type.is_symlink() {
            anyhow::bail!("agent artifact contains a symlink")
        }
        if file_type.is_dir() {
            collect_markdown(&entry.path(), candidates)?;
        } else if file_type.is_file()
            && entry
                .path()
                .extension()
                .is_some_and(|ext| ext.eq_ignore_ascii_case("md"))
        {
            candidates.push(entry.path());
        }
    }
    Ok(())
}

fn validate_agent_document(bytes: &[u8]) -> Result<()> {
    let text = std::str::from_utf8(bytes).context("agent document is not UTF-8")?;
    let body = text
        .strip_prefix("---\n")
        .or_else(|| text.strip_prefix("---\r\n"))
        .context("agent document must begin with YAML frontmatter")?;
    let (frontmatter, persona) = if let Some(index) = body.find("\n---\n") {
        (&body[..index], &body[index + 5..])
    } else if let Some(index) = body.find("\r\n---\r\n") {
        (&body[..index], &body[index + 7..])
    } else {
        anyhow::bail!("agent document frontmatter is not terminated")
    };
    let yaml: YamlValue =
        serde_yaml::from_str(frontmatter).context("parse agent YAML frontmatter")?;
    let map = yaml
        .as_mapping()
        .context("agent frontmatter must be a mapping")?;
    for field in ["name", "description"] {
        let value = map
            .get(YamlValue::String(field.to_string()))
            .and_then(YamlValue::as_str)
            .filter(|value| !value.trim().is_empty());
        if value.is_none() {
            anyhow::bail!("agent frontmatter requires a nonblank string {field}")
        }
    }
    if persona.trim().is_empty() {
        anyhow::bail!("agent document requires a nonblank persona body")
    }
    Ok(())
}

fn metadata_for(
    config: &SkillsConfig,
    resolution: &AgentInstallResolution,
    slug: &str,
    document: &[u8],
) -> Result<InstalledAgentMetadata> {
    let artifact = resolution
        .artifact
        .as_ref()
        .context("agent artifact disappeared during install")?;
    Ok(InstalledAgentMetadata {
        schema_version: RECORD_SCHEMA.to_string(),
        kind: "agent".to_string(),
        slug: slug.to_string(),
        version_id: resolution.plan.version_id.clone(),
        content_sha256: resolution.plan.content_sha256.clone(),
        installed_file_sha256: sha256_hex(document),
        artifact_id: artifact.id.clone(),
        artifact_sha256: artifact.sha256.clone(),
        artifact_size_bytes: artifact.size_bytes,
        artifact_media_type: artifact.media_type.clone(),
        source_id: resolution.version.source.source_id.clone(),
        source_snapshot_id: resolution.version.source.snapshot_id.clone(),
        source_revision: resolution.version.source.revision.clone(),
        source_path: resolution.version.source.path.clone(),
        server_url: kgoose_service_url(&config.kgoose_base_url, &config.kgoose_service_path),
        installed_at: iso8601_utc(unix_seconds()?),
        installed_via: resolution.installed_via.clone(),
    })
}

fn replace_pair(
    paths: &AgentPaths,
    document: &[u8],
    metadata: &InstalledAgentMetadata,
) -> Result<()> {
    replace_pair_with_rename(paths, document, metadata, |from, to| fs::rename(from, to))
}

fn replace_pair_with_rename<F>(
    paths: &AgentPaths,
    document: &[u8],
    metadata: &InstalledAgentMetadata,
    mut rename: F,
) -> Result<()>
where
    F: FnMut(&Path, &Path) -> std::io::Result<()>,
{
    let target_parent = paths
        .target
        .parent()
        .context("agent target has no parent")?;
    let state_parent = paths.state.parent().context("agent state has no parent")?;
    fs::create_dir_all(target_parent)
        .with_context(|| format!("create {}", target_parent.display()))?;
    fs::create_dir_all(state_parent)
        .with_context(|| format!("create {}", state_parent.display()))?;
    let suffix = unique_suffix();
    let target_stage = target_parent.join(format!(
        ".{}.stage-{suffix}",
        paths.target.file_name().unwrap().to_string_lossy()
    ));
    let state_stage = state_parent.join(format!(
        ".{}.stage-{suffix}",
        paths.state.file_name().unwrap().to_string_lossy()
    ));
    write_new_file(&target_stage, document)?;
    write_new_file(
        &state_stage,
        &serde_json::to_vec_pretty(metadata).context("serialize agent state")?,
    )?;
    let target_backup = backup_path(&paths.target, suffix);
    let state_backup = backup_path(&paths.state, suffix);
    let target_existed = paths.target.exists();
    let state_existed = paths.state.exists();
    let result = (|| -> Result<()> {
        if target_existed {
            rename(&paths.target, &target_backup)
                .with_context(|| format!("backup {}", paths.target.display()))?;
        }
        if state_existed {
            if let Err(error) = rename(&paths.state, &state_backup) {
                let operation =
                    anyhow::Error::new(error).context(format!("backup {}", paths.state.display()));
                return Err(with_recovery(
                    operation,
                    restore_pair(
                        &mut rename,
                        paths,
                        &target_backup,
                        &state_backup,
                        target_existed,
                        false,
                        false,
                    ),
                ));
            }
        }
        if let Err(error) = rename(&target_stage, &paths.target) {
            let operation =
                anyhow::Error::new(error).context(format!("install {}", paths.target.display()));
            return Err(with_recovery(
                operation,
                restore_pair(
                    &mut rename,
                    paths,
                    &target_backup,
                    &state_backup,
                    target_existed,
                    state_existed,
                    false,
                ),
            ));
        }
        if let Err(error) = rename(&state_stage, &paths.state) {
            let operation =
                anyhow::Error::new(error).context(format!("install {}", paths.state.display()));
            return Err(with_recovery(
                operation,
                restore_pair(
                    &mut rename,
                    paths,
                    &target_backup,
                    &state_backup,
                    target_existed,
                    state_existed,
                    true,
                ),
            ));
        }
        Ok(())
    })();
    match result {
        Ok(()) => {
            remove_backups(&target_backup, &state_backup)?;
            Ok(())
        }
        Err(operation) => Err(with_recovery(
            operation,
            remove_stages(&target_stage, &state_stage),
        )),
    }
}

fn remove_pair(paths: &AgentPaths, has_target: bool) -> Result<()> {
    let suffix = unique_suffix();
    let target_backup = backup_path(&paths.target, suffix);
    let state_backup = backup_path(&paths.state, suffix);
    if has_target {
        fs::rename(&paths.target, &target_backup)
            .with_context(|| format!("stage removal of {}", paths.target.display()))?;
    }
    if let Err(error) = fs::rename(&paths.state, &state_backup) {
        let operation = anyhow::Error::new(error)
            .context(format!("stage removal of {}", paths.state.display()));
        return Err(with_recovery(
            operation,
            restore_pair(
                &mut |from, to| fs::rename(from, to),
                paths,
                &target_backup,
                &state_backup,
                has_target,
                false,
                false,
            ),
        ));
    }
    if has_target {
        fs::remove_file(&target_backup)
            .with_context(|| format!("remove {}", paths.target.display()))?;
    }
    fs::remove_file(&state_backup).with_context(|| format!("remove {}", paths.state.display()))
}

fn restore_pair<F>(
    rename: &mut F,
    paths: &AgentPaths,
    target_backup: &Path,
    state_backup: &Path,
    target_existed: bool,
    state_existed: bool,
    target_replaced: bool,
) -> Result<()>
where
    F: FnMut(&Path, &Path) -> std::io::Result<()>,
{
    let mut failures = Vec::new();
    if target_replaced {
        if let Err(error) = fs::remove_file(&paths.target) {
            failures.push(format!(
                "remove replacement {}: {error}",
                paths.target.display()
            ));
        }
    }
    if state_existed {
        if let Err(error) = rename(state_backup, &paths.state) {
            failures.push(format!("restore {}: {error}", paths.state.display()));
        }
    }
    if target_existed {
        if let Err(error) = rename(target_backup, &paths.target) {
            failures.push(format!("restore {}: {error}", paths.target.display()));
        }
    }
    if failures.is_empty() {
        Ok(())
    } else {
        anyhow::bail!(failures.join("; "))
    }
}

fn with_recovery(operation: anyhow::Error, recovery: Result<()>) -> anyhow::Error {
    match recovery {
        Ok(()) => operation,
        Err(recovery_error) => anyhow::anyhow!(
            "{operation:#}; recovery failed: {recovery_error:#}. Inspect the agent and state paths before retrying."
        ),
    }
}

fn remove_stages(target_stage: &Path, state_stage: &Path) -> Result<()> {
    for stage in [target_stage, state_stage] {
        match fs::remove_file(stage) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => {
                return Err(error).with_context(|| format!("remove stage {}", stage.display()))
            }
        }
    }
    Ok(())
}

fn remove_backups(target_backup: &Path, state_backup: &Path) -> Result<()> {
    for backup in [target_backup, state_backup] {
        match fs::remove_file(backup) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => {
                return Err(error).with_context(|| format!("remove backup {}", backup.display()))
            }
        }
    }
    Ok(())
}

fn backup_path(path: &Path, suffix: u128) -> PathBuf {
    path.parent().unwrap().join(format!(
        ".{}.previous-{suffix}",
        path.file_name().unwrap().to_string_lossy()
    ))
}

fn write_new_file(path: &Path, bytes: &[u8]) -> Result<()> {
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(path)
        .with_context(|| format!("create {}", path.display()))?;
    file.write_all(bytes)
        .with_context(|| format!("write {}", path.display()))?;
    file.sync_all()
        .with_context(|| format!("sync {}", path.display()))
}

fn unique_suffix() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos()
}

fn unix_seconds() -> Result<u64> {
    Ok(SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .context("system clock is before UNIX epoch")?
        .as_secs())
}

struct AgentLock {
    path: PathBuf,
}

impl AgentLock {
    fn acquire(path: &Path) -> Result<Self> {
        let parent = path.parent().context("agent lock has no parent")?;
        fs::create_dir_all(parent).with_context(|| format!("create {}", parent.display()))?;
        for _ in 0..2 {
            match fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(path)
            {
                Ok(mut file) => {
                    let _ = writeln!(file, "{}", std::process::id());
                    return Ok(Self {
                        path: path.to_path_buf(),
                    });
                }
                Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
                    let stale = fs::metadata(path)
                        .and_then(|metadata| metadata.modified())
                        .ok()
                        .and_then(|modified| modified.elapsed().ok())
                        .is_some_and(|age| age.as_secs() > LOCK_STALE_SECS);
                    if stale {
                        let _ = fs::remove_file(path);
                        continue;
                    }
                    return Err(failure(
                        exit_codes::FS_CONFLICT,
                        "agent_locked",
                        format!(
                            "another bb agents operation is running; remove {} if this is stale",
                            path.display()
                        ),
                    ));
                }
                Err(error) => {
                    return Err(error).with_context(|| format!("create {}", path.display()))
                }
            }
        }
        Err(failure(
            exit_codes::FS_CONFLICT,
            "agent_locked",
            format!("could not acquire {}", path.display()),
        ))
    }
}

impl Drop for AgentLock {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.path);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn temp_paths(slug: &str) -> (tempfile::TempDir, AgentPaths) {
        let root = tempfile::tempdir().unwrap();
        let paths = AgentPaths {
            target: root.path().join("agents").join(format!("{slug}.md")),
            state: root.path().join("state").join(format!("{slug}.json")),
            lock: root.path().join("lock"),
        };
        (root, paths)
    }

    fn record(slug: &str, contents: &[u8]) -> InstalledAgentMetadata {
        InstalledAgentMetadata {
            schema_version: RECORD_SCHEMA.to_string(),
            kind: "agent".to_string(),
            slug: slug.to_string(),
            version_id: "v1".to_string(),
            content_sha256: "content".to_string(),
            installed_file_sha256: sha256_hex(contents),
            artifact_id: "artifact".to_string(),
            artifact_sha256: "artifact-sha".to_string(),
            artifact_size_bytes: 1,
            artifact_media_type: "application/zip".to_string(),
            source_id: "source".to_string(),
            source_snapshot_id: "snapshot".to_string(),
            source_revision: "revision".to_string(),
            source_path: "agents/demo.md".to_string(),
            server_url: "http://localhost".to_string(),
            installed_at: "0Z".to_string(),
            installed_via: "explicit".to_string(),
        }
    }

    #[test]
    fn rejects_unsafe_slugs() {
        for slug in ["", "../demo", "Demo", "a/b", "a.b"] {
            assert!(validate_slug(slug).is_err());
        }
        assert!(validate_slug("release-notes_2").is_ok());
    }

    #[test]
    fn classifies_absent_exact_missing_and_changed_content() {
        let (_root, paths) = temp_paths("demo");
        assert!(matches!(
            classify(&paths, "demo").unwrap(),
            AgentOwnership::Absent
        ));
        let contents = b"---\nname: Demo\ndescription: Test\n---\nPersona";
        fs::create_dir_all(paths.target.parent().unwrap()).unwrap();
        fs::create_dir_all(paths.state.parent().unwrap()).unwrap();
        fs::write(&paths.target, contents).unwrap();
        fs::write(
            &paths.state,
            serde_json::to_vec(&record("demo", contents)).unwrap(),
        )
        .unwrap();
        assert!(matches!(
            classify(&paths, "demo").unwrap(),
            AgentOwnership::ManagedExact(_)
        ));
        fs::remove_file(&paths.target).unwrap();
        assert!(matches!(
            classify(&paths, "demo").unwrap(),
            AgentOwnership::ManagedMissingFile(_)
        ));
        fs::write(&paths.target, b"changed").unwrap();
        assert!(matches!(
            classify(&paths, "demo").unwrap(),
            AgentOwnership::ProtectedConflict { .. }
        ));
    }

    #[test]
    fn validates_agent_document_contract() {
        assert!(
            validate_agent_document(b"---\nname: Demo\ndescription: Test\n---\nPersona").is_ok()
        );
        assert!(validate_agent_document(b"---\nname: Demo\n---\nPersona").is_err());
        assert!(validate_agent_document(b"---\nname: Demo\ndescription: Test\n---\n  ").is_err());
    }

    #[test]
    fn accepts_crlf_frontmatter_with_a_short_persona() {
        assert!(
            validate_agent_document(b"---\r\nname: Demo\r\ndescription: Test\r\n---\r\nI").is_ok()
        );
    }

    #[test]
    fn restores_existing_pair_when_target_stage_rename_fails() {
        let (_root, paths) = temp_paths("demo");
        let old_document = b"---\nname: Demo\ndescription: Old\n---\nOld";
        let old_state = serde_json::to_vec(&record("demo", old_document)).unwrap();
        fs::create_dir_all(paths.target.parent().unwrap()).unwrap();
        fs::create_dir_all(paths.state.parent().unwrap()).unwrap();
        fs::write(&paths.target, old_document).unwrap();
        fs::write(&paths.state, &old_state).unwrap();

        let replacement = b"---\nname: Demo\ndescription: New\n---\nNew";
        let error = replace_pair_with_rename(
            &paths,
            replacement,
            &record("demo", replacement),
            |from, to| {
                if from.parent() == paths.target.parent()
                    && from
                        .file_name()
                        .is_some_and(|name| name.to_string_lossy().starts_with(".demo.md.stage-"))
                {
                    return Err(std::io::Error::other(
                        "injected target-stage rename failure",
                    ));
                }
                fs::rename(from, to)
            },
        )
        .unwrap_err();

        assert!(format!("{error:#}").contains("injected target-stage rename failure"));
        assert_eq!(fs::read(&paths.target).unwrap(), old_document);
        assert_eq!(fs::read(&paths.state).unwrap(), old_state);
    }

    #[test]
    fn reports_failed_pair_recovery_with_canonical_paths() {
        let (_root, paths) = temp_paths("demo");
        fs::create_dir_all(paths.target.parent().unwrap()).unwrap();
        let suffix = unique_suffix();
        let recovery = restore_pair(
            &mut |_, _| Err(std::io::Error::other("injected restore failure")),
            &paths,
            &backup_path(&paths.target, suffix),
            &backup_path(&paths.state, suffix),
            true,
            true,
            false,
        );

        let error = with_recovery(anyhow::anyhow!("install failed"), recovery);

        let message = format!("{error:#}");
        assert!(message.contains("recovery failed"));
        assert!(message.contains(&paths.target.display().to_string()));
        assert!(message.contains(&paths.state.display().to_string()));
    }

    #[test]
    fn removes_orphaned_managed_state_without_requiring_a_target_backup() {
        let (_root, paths) = temp_paths("demo");
        fs::create_dir_all(paths.state.parent().unwrap()).unwrap();
        fs::write(
            &paths.state,
            serde_json::to_vec(&record("demo", b"old")).unwrap(),
        )
        .unwrap();

        remove_pair(&paths, false).unwrap();

        assert!(!paths.target.exists());
        assert!(!paths.state.exists());
    }

    #[test]
    fn protected_removal_preserves_changed_agent_and_state() {
        let (_root, paths) = temp_paths("demo");
        let original = b"---\nname: Demo\ndescription: Managed\n---\nPersona";
        let changed = b"---\nname: Demo\ndescription: Local\n---\nPersona";
        let state = serde_json::to_vec(&record("demo", original)).unwrap();
        fs::create_dir_all(paths.target.parent().unwrap()).unwrap();
        fs::create_dir_all(paths.state.parent().unwrap()).unwrap();
        fs::write(&paths.target, changed).unwrap();
        fs::write(&paths.state, &state).unwrap();

        let result = remove_at_paths(&paths, "demo").unwrap();

        assert_eq!(result.status, AgentLifecycleStatus::Conflict);
        assert_eq!(fs::read(&paths.target).unwrap(), changed);
        assert_eq!(fs::read(&paths.state).unwrap(), state);
    }

    #[test]
    fn up_to_date_result_does_not_write_the_managed_pair() {
        let (_root, paths) = temp_paths("demo");
        let document = b"---\nname: Demo\ndescription: Test\n---\nPersona";
        let state = serde_json::to_vec(&record("demo", document)).unwrap();
        fs::create_dir_all(paths.target.parent().unwrap()).unwrap();
        fs::create_dir_all(paths.state.parent().unwrap()).unwrap();
        fs::write(&paths.target, document).unwrap();
        fs::write(&paths.state, &state).unwrap();

        let mut downloaded = false;
        let downloaded_document = download_if_required(
            &AgentOwnership::ManagedExact(record("demo", document)),
            "noop",
            || {
                downloaded = true;
                anyhow::bail!("a no-op must not download an artifact")
            },
        )
        .unwrap();
        let result = up_to_date_result(
            "demo",
            &paths,
            record("demo", document),
            "current".to_string(),
        );

        assert!(downloaded_document.is_none());
        assert!(!downloaded);
        assert_eq!(result.status, AgentLifecycleStatus::UpToDate);
        assert_eq!(fs::read(&paths.target).unwrap(), document);
        assert_eq!(fs::read(&paths.state).unwrap(), state);
    }
}

//! Backend-owned model-provider native sign-in setup state.
//!
//! The Rust backend is the source of truth for a model provider's native
//! sign-in progress: a spawned tokio task owns the whole `goose configure`
//! shell flow and writes phase / streamed output / status into
//! [`ModelSetupRegistry`], a managed Tauri state keyed by provider id. The
//! frontend only *kicks off* (`start_model_setup`) and *observes* (the
//! `model-setup:state` event + `list_model_setup_status` rehydration) the
//! operation, so progress survives navigating away, coming back, and a full
//! window reload — and the sign-in keeps advancing the whole time because it no
//! longer lives in the row.
//!
//! This mirrors `agent_setup.rs` (the agent-provider Phase 1) closely: same
//! registry / begin / idempotent-start shape, same coarse terminal-entry GC
//! sweep, same single bounded-snapshot event. The one intentional divergence is
//! that `mutate` emits the snapshot while still holding the lock: the agent
//! fix-chain streams its output through a single serial callback, but the native
//! sign-in reads stdout and stderr on two concurrent tasks, so emitting *after*
//! the lock is released could deliver snapshots out of mutation order and — since
//! the store replaces its view wholesale — momentarily drop the latest line. The
//! model path is also simpler than the agent fix-chain — there is a single
//! operation (the native sign-in), so there is no `action` discriminant and no
//! install loop; the only recipe captured at start time is the provider's
//! native-connect label, which is enough to rebuild the `goose configure`
//! command after a reload.

use std::collections::HashMap;
use std::sync::{Arc, Mutex, MutexGuard};

use tauri::{AppHandle, Emitter, State};
use tokio::io::{AsyncBufReadExt, BufReader};

use crate::services::acp::goose_serve::get_goose_command;

/// Cap the buffered output so emitting the full snapshot on every streamed line
/// stays cheap and the event payload stays bounded. Lifted from the row (which
/// used the same 8-line window via `MAX_SETUP_OUTPUT_LINES`) into the backend
/// now that the registry owns the buffer.
const MAX_OUTPUT_LINES: usize = 8;

/// Coarse TTL backstop: a terminal (`succeeded`/`failed`) entry is swept on the
/// next registry write once it is older than this, so a result is never
/// orphaned if its row never mounts again to call `clear_model_setup_status`.
/// `running` entries are never swept.
const GC_TTL_MS: u64 = 10 * 60 * 1000;

/// The current step of the sign-in. Drives the row's progress label. The native
/// sign-in is a single shell flow, so there are only the in-flight
/// (`authenticating`) and terminal (`idle`) phases.
#[derive(Clone, Copy, Debug, PartialEq, Eq, serde::Serialize)]
#[serde(rename_all = "camelCase")]
enum ModelSetupPhase {
    Idle,
    Authenticating,
}

/// Lifecycle of an operation. Terminal states (`succeeded`/`failed`) persist
/// long enough for a reloaded row to read the result, then are GC'd.
#[derive(Clone, Copy, Debug, PartialEq, Eq, serde::Serialize)]
#[serde(rename_all = "camelCase")]
enum ModelSetupStatus {
    Running,
    Succeeded,
    Failed,
}

/// One model provider's in-flight (or just-finished) sign-in operation. The
/// whole snapshot is emitted on every change — it is small and bounded, so the
/// store can replace its view wholesale with no incremental-merge to get wrong.
#[derive(Clone, Debug, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ModelSetupOperation {
    phase: ModelSetupPhase,
    status: ModelSetupStatus,
    /// Bounded to [`MAX_OUTPUT_LINES`]; the streamed (and relevance-filtered)
    /// `goose configure` output.
    output: Vec<String>,
    /// On failure, the raw sign-in error the row surfaces verbatim.
    error: Option<String>,
    /// For the GC backstop. Milliseconds since the Unix epoch.
    updated_at_ms: u64,
}

impl ModelSetupOperation {
    fn running() -> Self {
        ModelSetupOperation {
            phase: ModelSetupPhase::Authenticating,
            status: ModelSetupStatus::Running,
            output: Vec::new(),
            error: None,
            updated_at_ms: now_ms(),
        }
    }
}

/// The execution recipe captured at click time. The row already knows the
/// provider's native-connect label, so it passes it in and the backend rebuilds
/// the `goose configure` command autonomously — which is what lets the sign-in
/// survive a reload (the recipe doesn't depend on any live row state).
#[derive(Debug, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ModelSetupPlan {
    /// The provider's `nativeConnectQuery` (e.g. `databricks`), piped into
    /// `goose configure` to select the provider.
    provider_label: String,
}

/// Managed Tauri state: `providerId -> ModelSetupOperation`. Keying by provider
/// lets sign-ins across different providers run concurrently. The spawned task
/// owns an `Arc` clone so it keeps writing after `start_model_setup` returns.
#[derive(Default, Clone)]
pub struct ModelSetupRegistry(Arc<Mutex<HashMap<String, ModelSetupOperation>>>);

impl ModelSetupRegistry {
    fn lock(&self) -> MutexGuard<'_, HashMap<String, ModelSetupOperation>> {
        // Tolerate a poisoned mutex: the map is plain data and a panic in one
        // operation must not wedge every other provider's sign-in.
        self.0.lock().unwrap_or_else(|poison| poison.into_inner())
    }

    /// Idempotent start. If an operation is already `running` for this provider,
    /// returns `(false, snapshot)` and leaves it untouched (a reloaded row
    /// re-fires `start` on mount; this guard prevents a double-start).
    /// Otherwise seeds a fresh running operation, replacing any terminal entry,
    /// and returns `(true, snapshot)` so the caller spawns the task.
    fn begin(&self, provider_id: &str) -> (bool, ModelSetupOperation) {
        let mut map = self.lock();
        if let Some(existing) = map.get(provider_id) {
            if existing.status == ModelSetupStatus::Running {
                return (false, existing.clone());
            }
        }
        sweep_terminal(&mut map, now_ms(), GC_TTL_MS);
        let operation = ModelSetupOperation::running();
        map.insert(provider_id.to_string(), operation.clone());
        (true, operation)
    }

    /// Apply `mutate` to the provider's operation (if present), bump
    /// `updated_at_ms`, then — **still holding the lock** — hand the new snapshot
    /// to `on_snapshot` before releasing it and GC'ing stale terminal entries.
    /// Emitting from inside `on_snapshot` (rather than off the returned value)
    /// is what keeps the emit order matching the mutation order: two reader
    /// tasks each appending a line can't interleave a mutation between another's
    /// mutate-and-emit, so the wholesale store replace never ends on a stale
    /// snapshot missing the latest line. Returns the new snapshot, or `None` if
    /// the entry was already cleared.
    fn mutate(
        &self,
        provider_id: &str,
        mutate: impl FnOnce(&mut ModelSetupOperation),
        on_snapshot: impl FnOnce(&ModelSetupOperation),
    ) -> Option<ModelSetupOperation> {
        let mut map = self.lock();
        let snapshot = {
            let operation = map.get_mut(provider_id)?;
            mutate(operation);
            operation.updated_at_ms = now_ms();
            on_snapshot(operation);
            operation.clone()
        };
        sweep_terminal(&mut map, now_ms(), GC_TTL_MS);
        Some(snapshot)
    }

    fn get(&self, provider_id: &str) -> Option<ModelSetupOperation> {
        self.lock().get(provider_id).cloned()
    }

    fn list(&self) -> Vec<(String, ModelSetupOperation)> {
        self.lock()
            .iter()
            .map(|(id, operation)| (id.clone(), operation.clone()))
            .collect()
    }

    fn remove(&self, provider_id: &str) {
        self.lock().remove(provider_id);
    }
}

fn now_ms() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|elapsed| elapsed.as_millis() as u64)
        .unwrap_or(0)
}

/// Drop terminal entries older than `ttl_ms`. `running` operations are kept
/// regardless of age so an in-flight sign-in is never swept out from under
/// itself.
fn sweep_terminal(map: &mut HashMap<String, ModelSetupOperation>, now_ms: u64, ttl_ms: u64) {
    map.retain(|_, operation| {
        operation.status == ModelSetupStatus::Running
            || now_ms.saturating_sub(operation.updated_at_ms) < ttl_ms
    });
}

/// Append a streamed line into the bounded output buffer (oldest lines drop
/// first once the cap is hit).
fn push_output_line(output: &mut Vec<String>, line: &str) {
    output.push(line.to_string());
    if output.len() > MAX_OUTPUT_LINES {
        let overflow = output.len() - MAX_OUTPUT_LINES;
        output.drain(0..overflow);
    }
}

#[derive(Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
struct ModelSetupStateEvent {
    provider_id: String,
    operation: ModelSetupOperation,
}

fn emit_state(app: &AppHandle, provider_id: &str, operation: &ModelSetupOperation) {
    let _ = app.emit(
        "model-setup:state",
        ModelSetupStateEvent {
            provider_id: provider_id.to_string(),
            operation: operation.clone(),
        },
    );
}

/// Mutate the operation and emit the resulting snapshot in one step. The emit
/// runs while the registry lock is still held (see [`ModelSetupRegistry::mutate`]),
/// so concurrent writers emit in mutation order. A no-op if the entry was
/// already cleared (e.g. the row consumed a terminal state).
fn apply_and_emit(
    app: &AppHandle,
    registry: &ModelSetupRegistry,
    provider_id: &str,
    mutate: impl FnOnce(&mut ModelSetupOperation),
) {
    registry.mutate(provider_id, mutate, |operation| {
        emit_state(app, provider_id, operation);
    });
}

fn append_output(app: &AppHandle, registry: &ModelSetupRegistry, provider_id: &str, line: &str) {
    apply_and_emit(app, registry, provider_id, |operation| {
        push_output_line(&mut operation.output, line);
    });
}

fn shell_quote(value: &str) -> String {
    format!("'{}'", value.replace('\'', "'\"'\"'"))
}

fn strip_ansi(value: &str) -> String {
    let mut chars = value.chars().peekable();
    let mut output = String::new();

    while let Some(ch) = chars.next() {
        if ch == '\u{1b}' {
            if chars.peek() == Some(&'[') {
                chars.next();
                for next in chars.by_ref() {
                    if ('\u{40}'..='\u{7e}').contains(&next) {
                        break;
                    }
                }
            }
            continue;
        }

        if ch.is_ascii_control() {
            continue;
        }

        output.push(ch);
    }

    output
}

fn normalize_output_line(line: &str) -> Option<String> {
    let cleaned = strip_ansi(line);
    let trimmed = cleaned
        .trim()
        .trim_start_matches(['│', '┌', '└', '◆', '◇', '●', '○'])
        .trim();

    if trimmed.is_empty()
        || trimmed == "Configure Providers"
        || trimmed == "What would you like to configure?"
        || trimmed == "Which model provider should we use?"
        || trimmed == "This will update your existing config files"
        || trimmed.starts_with("if you prefer, you can edit them directly at")
    {
        return None;
    }

    Some(trimmed.to_string())
}

fn is_relevant_output(line: &str) -> bool {
    line.starts_with("Configuring ")
        || line.starts_with("Please visit ")
        || line.starts_with("Open ")
        || line.starts_with("Opening ")
        || line.starts_with("Waiting ")
        || line.starts_with("Authentication")
        || line.starts_with("Authenticated")
        || line.starts_with("Saved ")
        || line.contains("oauth")
        || line.contains("OAuth")
        || line.contains("device code")
        || line.contains("login/device")
        || line.contains("browser")
}

/// Idempotently kick off a provider's native sign-in and return immediately with
/// the seeded snapshot. The sign-in runs to completion in a spawned task that
/// owns an `Arc` clone of the registry + the `AppHandle`, so it keeps advancing
/// (and writing progress) regardless of which row is mounted.
#[tauri::command]
pub fn start_model_setup(
    app_handle: AppHandle,
    registry: State<'_, ModelSetupRegistry>,
    provider_id: String,
    plan: ModelSetupPlan,
) -> ModelSetupOperation {
    let (started, snapshot) = registry.begin(&provider_id);
    emit_state(&app_handle, &provider_id, &snapshot);
    if !started {
        // Already running — the idempotent no-op path (a reloaded row re-firing
        // start on mount). Return the live snapshot without a second task.
        return snapshot;
    }

    let registry = registry.inner().clone();
    let app = app_handle.clone();
    let provider_for_task = provider_id.clone();
    tauri::async_runtime::spawn(async move {
        run_model_setup(app, registry, provider_for_task, plan).await;
    });
    snapshot
}

#[tauri::command]
pub fn get_model_setup_status(
    registry: State<'_, ModelSetupRegistry>,
    provider_id: String,
) -> Option<ModelSetupOperation> {
    registry.get(&provider_id)
}

#[tauri::command]
pub fn list_model_setup_status(
    registry: State<'_, ModelSetupRegistry>,
) -> Vec<(String, ModelSetupOperation)> {
    registry.list()
}

#[tauri::command]
pub fn clear_model_setup_status(registry: State<'_, ModelSetupRegistry>, provider_id: String) {
    registry.remove(&provider_id);
}

/// Run the native sign-in to completion, then write the terminal status. The
/// frontend does the post-success verification (it re-reads provider status over
/// ACP), so the backend just runs the shell flow and reports succeeded/failed.
async fn run_model_setup(
    app: AppHandle,
    registry: ModelSetupRegistry,
    provider_id: String,
    plan: ModelSetupPlan,
) {
    let result = run_native_connect(&app, &registry, &provider_id, &plan).await;

    apply_and_emit(&app, &registry, &provider_id, |operation| {
        operation.phase = ModelSetupPhase::Idle;
        match &result {
            Ok(()) => {
                operation.status = ModelSetupStatus::Succeeded;
                operation.error = None;
            }
            Err(message) => {
                operation.status = ModelSetupStatus::Failed;
                operation.error = Some(message.clone());
            }
        }
    });
}

/// Build the `goose configure` command for `provider_label` and stream it
/// through the registry. Mirrors the former in-row native-connect, now owned by
/// the backend task so it survives a reload.
async fn run_native_connect(
    app: &AppHandle,
    registry: &ModelSetupRegistry,
    provider_id: &str,
    plan: &ModelSetupPlan,
) -> Result<(), String> {
    if cfg!(target_os = "windows") {
        return Err("Native Berd sign-in is not supported on Windows yet".to_string());
    }

    let goose_command = get_goose_command(app)?;
    let quoted_label = shell_quote(&plan.provider_label);
    let quoted_binary = shell_quote(&goose_command.as_std().get_program().to_string_lossy());

    let command = if cfg!(target_os = "linux") {
        format!(
            "printf '\\n%s\\n' {quoted_label} | script -qf /dev/null -c '{quoted_binary} configure'",
        )
    } else {
        format!("printf '\\n%s\\n' {quoted_label} | script -q /dev/null {quoted_binary} configure",)
    };

    run_shell_command(app, registry, provider_id, &command).await
}

/// Spawn the sign-in shell command, streaming each relevant (normalized,
/// ANSI-stripped, relevance-gated) line into the registry — which emits
/// `model-setup:state` — instead of the old per-line `model-setup:output`. The
/// two reader tasks append *and* emit their snapshot under the registry mutex
/// (see [`ModelSetupRegistry::mutate`]), so the emit order matches the mutation
/// order: concurrent stdout/stderr writes can't emit out of order and leave the
/// store's wholesale replace ending on a stale snapshot missing the latest line.
async fn run_shell_command(
    app_handle: &AppHandle,
    registry: &ModelSetupRegistry,
    provider_id: &str,
    command: &str,
) -> Result<(), String> {
    let shell = if cfg!(target_os = "windows") {
        "cmd"
    } else {
        "sh"
    };
    let flag = if cfg!(target_os = "windows") {
        "/C"
    } else {
        "-c"
    };

    append_output(
        app_handle,
        registry,
        provider_id,
        "Starting Berd sign-in...",
    );

    let mut process = tokio::process::Command::new(shell);
    process
        .arg(flag)
        .arg(command)
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    crate::services::process::apply_no_window_async(&mut process);
    let mut child = process
        .spawn()
        .map_err(|e| format!("Failed to start sign-in flow: {e}"))?;

    let stdout = child.stdout.take();
    let stderr = child.stderr.take();

    let provider_id_stdout = provider_id.to_string();
    let app_stdout = app_handle.clone();
    let registry_stdout = registry.clone();

    let stdout_task = tokio::spawn(async move {
        let mut has_relevant_output = false;
        if let Some(stdout) = stdout {
            let reader = BufReader::new(stdout);
            let mut lines = reader.lines();
            while let Ok(Some(line)) = lines.next_line().await {
                let Some(line) = normalize_output_line(&line) else {
                    continue;
                };

                if !has_relevant_output && is_relevant_output(&line) {
                    has_relevant_output = true;
                }

                if has_relevant_output {
                    append_output(&app_stdout, &registry_stdout, &provider_id_stdout, &line);
                }
            }
        }
    });

    let provider_id_stderr = provider_id.to_string();
    let app_stderr = app_handle.clone();
    let registry_stderr = registry.clone();

    let stderr_task = tokio::spawn(async move {
        let mut has_relevant_output = false;
        if let Some(stderr) = stderr {
            let reader = BufReader::new(stderr);
            let mut lines = reader.lines();
            while let Ok(Some(line)) = lines.next_line().await {
                let Some(line) = normalize_output_line(&line) else {
                    continue;
                };

                if !has_relevant_output && is_relevant_output(&line) {
                    has_relevant_output = true;
                }

                if has_relevant_output {
                    append_output(&app_stderr, &registry_stderr, &provider_id_stderr, &line);
                }
            }
        }
    });

    let _ = tokio::join!(stdout_task, stderr_task);

    let status = child
        .wait()
        .await
        .map_err(|e| format!("Failed to wait for sign-in flow: {e}"))?;

    if status.success() {
        Ok(())
    } else {
        let code = status.code().unwrap_or(-1);
        Err(format!("Berd sign-in exited with code {code}"))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn begin_seeds_running_and_is_idempotent() {
        let registry = ModelSetupRegistry::default();

        let (started, operation) = registry.begin("databricks_v2");
        assert!(started);
        assert_eq!(operation.status, ModelSetupStatus::Running);
        assert_eq!(operation.phase, ModelSetupPhase::Authenticating);

        // Re-firing while running is a no-op that returns the live snapshot.
        let (started_again, again) = registry.begin("databricks_v2");
        assert!(!started_again);
        assert_eq!(again.status, ModelSetupStatus::Running);
        assert_eq!(registry.list().len(), 1);

        // Once terminal, a fresh begin replaces the entry and starts over.
        registry.mutate(
            "databricks_v2",
            |operation| {
                operation.status = ModelSetupStatus::Failed;
                operation.phase = ModelSetupPhase::Idle;
            },
            |_| {},
        );
        let (started_after_terminal, _) = registry.begin("databricks_v2");
        assert!(started_after_terminal);
        assert_eq!(
            registry.get("databricks_v2").unwrap().status,
            ModelSetupStatus::Running
        );
    }

    #[test]
    fn begin_starts_in_authenticating_phase() {
        let registry = ModelSetupRegistry::default();
        let (_, operation) = registry.begin("databricks_v2");
        assert_eq!(operation.phase, ModelSetupPhase::Authenticating);
    }

    #[test]
    fn mutate_transitions_phase_and_status() {
        let registry = ModelSetupRegistry::default();
        registry.begin("databricks_v2");

        registry.mutate(
            "databricks_v2",
            |operation| {
                operation.status = ModelSetupStatus::Succeeded;
                operation.phase = ModelSetupPhase::Idle;
            },
            |_| {},
        );
        let operation = registry.get("databricks_v2").unwrap();
        assert_eq!(operation.status, ModelSetupStatus::Succeeded);
        assert_eq!(operation.phase, ModelSetupPhase::Idle);
    }

    #[test]
    fn mutate_emits_the_applied_snapshot_under_lock() {
        let registry = ModelSetupRegistry::default();
        registry.begin("databricks_v2");

        // `on_snapshot` runs inside the lock and observes the just-applied
        // mutation, so emits stay ordered with mutations even when the two
        // reader tasks append concurrently.
        let mut emitted_output = None;
        registry.mutate(
            "databricks_v2",
            |operation| operation.output.push("hello".into()),
            |operation| emitted_output = Some(operation.output.clone()),
        );
        assert_eq!(emitted_output, Some(vec!["hello".to_string()]));
    }

    #[test]
    fn mutate_is_a_noop_for_a_cleared_entry() {
        let registry = ModelSetupRegistry::default();
        let mut emitted = false;
        assert!(registry
            .mutate(
                "never-started",
                |operation| operation.output.push("x".into()),
                |_| emitted = true,
            )
            .is_none());
        // No entry → no mutation and, crucially, no emit (otherwise a cleared
        // row could be resurrected by a stale snapshot).
        assert!(!emitted);
    }

    #[test]
    fn push_output_line_caps_to_the_window() {
        let mut output = Vec::new();
        for index in 0..(MAX_OUTPUT_LINES + 25) {
            push_output_line(&mut output, &format!("line {index}"));
        }
        assert_eq!(output.len(), MAX_OUTPUT_LINES);
        // Oldest lines drop first; the last line is retained.
        assert_eq!(output.first().unwrap(), "line 25");
        assert_eq!(
            output.last().unwrap(),
            &format!("line {}", MAX_OUTPUT_LINES + 24)
        );
    }

    fn operation_at(status: ModelSetupStatus, updated_at_ms: u64) -> ModelSetupOperation {
        ModelSetupOperation {
            phase: ModelSetupPhase::Idle,
            status,
            output: Vec::new(),
            error: None,
            updated_at_ms,
        }
    }

    #[test]
    fn sweep_removes_stale_terminal_but_keeps_running_and_fresh() {
        let now = 1_000_000u64;
        let mut map = HashMap::new();
        // Running entries are never swept, even when older than the TTL.
        map.insert(
            "running".to_string(),
            operation_at(ModelSetupStatus::Running, 0),
        );
        map.insert(
            "stale".to_string(),
            operation_at(ModelSetupStatus::Succeeded, now - GC_TTL_MS - 1),
        );
        map.insert(
            "fresh".to_string(),
            operation_at(ModelSetupStatus::Failed, now - 1_000),
        );

        sweep_terminal(&mut map, now, GC_TTL_MS);

        assert!(map.contains_key("running"));
        assert!(!map.contains_key("stale"));
        assert!(map.contains_key("fresh"));
    }

    #[test]
    fn normalize_output_line_strips_ansi_and_drops_noise() {
        // ANSI colour escapes are stripped from a relevant line.
        assert_eq!(
            normalize_output_line("\x1b[32mAuthenticated as user@example.com\x1b[0m"),
            Some("Authenticated as user@example.com".to_string())
        );
        // UTF-8 prompt borders survive stripping so sign-in URLs remain relevant.
        assert_eq!(
            normalize_output_line("\x1b[32m│ Please visit https://example.com/login/device\x1b[0m"),
            Some("Please visit https://example.com/login/device".to_string())
        );
        // A plain relevant line passes through unchanged.
        assert_eq!(
            normalize_output_line("Please visit https://example.com"),
            Some("Please visit https://example.com".to_string())
        );
        // Structural `goose configure` prompts and blank lines are dropped.
        assert_eq!(normalize_output_line("   Configure Providers   "), None);
        assert_eq!(normalize_output_line(""), None);
    }

    #[test]
    fn is_relevant_output_gates_on_sign_in_signal() {
        // Sign-in-relevant lines pass; incidental chatter is held back until one
        // does (mirrors the per-stream `has_relevant_output` latch).
        assert!(is_relevant_output(
            "Please visit https://example.com/login/device"
        ));
        assert!(is_relevant_output("Authenticated as user@example.com"));
        assert!(is_relevant_output("Opening browser..."));
        assert!(!is_relevant_output("some unrelated log line"));
    }
}

import type { ProviderDisplayInfo } from "@/shared/types/providers";

export const AGENT_SETUP_FAILURE_SIMULATION_KEY = "goose:dev:agentSetupFailure";

type AgentSetupFailureSimulationKind = "existing_file" | "unsupported_platform";

interface AgentSetupFailureSimulation {
  providerId: string;
  kind: AgentSetupFailureSimulationKind;
  path?: string;
}

function isDevRuntime() {
  return import.meta.env.DEV;
}

function parseSimulation(
  raw: string | null,
): AgentSetupFailureSimulation | null {
  if (!raw) return null;

  try {
    const parsed = JSON.parse(raw) as Partial<AgentSetupFailureSimulation>;
    if (!parsed.providerId) return null;
    return {
      providerId: parsed.providerId,
      kind:
        parsed.kind === "unsupported_platform"
          ? "unsupported_platform"
          : "existing_file",
      path: parsed.path,
    };
  } catch {
    return {
      providerId: raw,
      kind: "existing_file",
    };
  }
}

export function getAgentSetupFailureSimulation(
  providerId: string,
): AgentSetupFailureSimulation | null {
  if (!isDevRuntime() || typeof window === "undefined") return null;

  const simulation = parseSimulation(
    window.localStorage.getItem(AGENT_SETUP_FAILURE_SIMULATION_KEY),
  );

  return simulation?.providerId === providerId ? simulation : null;
}

export function getSimulatedAgentSetupFailureLines(
  provider: ProviderDisplayInfo,
  simulation: AgentSetupFailureSimulation,
): string[] {
  if (simulation.kind === "unsupported_platform") {
    return [
      "npm error code EBADPLATFORM",
      `npm error notsup Unsupported platform for ${provider.displayName}`,
      'npm error notsup wanted {"os":"win32","cpu":"x64"} (current: {"os":"darwin","cpu":"arm64"})',
    ];
  }

  const binaryName = provider.binaryName ?? provider.id;
  const path = simulation.path ?? `/opt/homebrew/bin/${binaryName}`;

  return [
    "npm error code EEXIST",
    `npm error path ${path}`,
    "npm error EEXIST: file already exists",
  ];
}

import { invoke } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";

// The backend (`src-tauri/src/commands/model_setup.rs`) is the source of truth
// for a model provider's native sign-in progress. The frontend only kicks an
// operation off (`startModelSetup`), observes it (`onModelSetupState` +
// `listModelSetupStatus` rehydration), and clears the terminal entry it
// consumes (`clearModelSetupStatus`). This is what lets the sign-in's spinner /
// streamed output / result survive navigation *and* a full window reload.

export type ModelSetupPhase = "idle" | "authenticating";

export type ModelSetupStatus = "running" | "succeeded" | "failed";

// One provider's in-flight (or just-finished) native sign-in. Mirrors the Rust
// `ModelSetupOperation` (camelCase serde); `updatedAtMs` is backend-only GC
// bookkeeping the UI ignores.
export interface ModelSetupOperation {
  phase: ModelSetupPhase;
  status: ModelSetupStatus;
  output: string[];
  error: string | null;
}

// The execution recipe captured at click time. The row already knows the
// provider's native-connect label, so the backend never has to re-derive it
// while still running the `goose configure` flow autonomously (survives reload).
export interface ModelSetupPlan {
  // The provider's `nativeConnectQuery` (e.g. `databricks`).
  providerLabel: string;
}

interface ModelSetupStateEvent {
  providerId: string;
  operation: ModelSetupOperation;
}

// Kick off (idempotently) a provider's native sign-in. Returns the seeded
// snapshot; if one is already running for this provider the backend no-ops and
// returns the live snapshot.
export async function startModelSetup(
  providerId: string,
  plan: ModelSetupPlan,
): Promise<ModelSetupOperation> {
  return invoke("start_model_setup", { providerId, plan });
}

export async function getModelSetupStatus(
  providerId: string,
): Promise<ModelSetupOperation | null> {
  return invoke("get_model_setup_status", { providerId });
}

// One call rehydrates every row on mount — cheaper than N `get`s when the
// providers screen mounts many rows.
export async function listModelSetupStatus(): Promise<
  [string, ModelSetupOperation][]
> {
  return invoke("list_model_setup_status");
}

export async function clearModelSetupStatus(providerId: string): Promise<void> {
  return invoke("clear_model_setup_status", { providerId });
}

// Subscribe to the single per-change snapshot event. Each event carries the
// full bounded operation, so the store replaces its view wholesale (no
// incremental merge to get wrong).
export function onModelSetupState(
  callback: (providerId: string, operation: ModelSetupOperation) => void,
): Promise<UnlistenFn> {
  return listen<ModelSetupStateEvent>("model-setup:state", (event) => {
    callback(event.payload.providerId, event.payload.operation);
  });
}

import { invoke } from "@tauri-apps/api/core";
import type { InstallationCohort } from "@/features/onboarding/model";

export const INSTALLATION_COHORT_TIMEOUT_MS = 5_000;

export function getInstallationCohort(): Promise<InstallationCohort> {
  return new Promise((resolve, reject) => {
    const timeout = window.setTimeout(
      () => reject(new Error("Installation cohort lookup timed out")),
      INSTALLATION_COHORT_TIMEOUT_MS,
    );
    void invoke<InstallationCohort>("get_installation_cohort").then(
      (cohort) => {
        window.clearTimeout(timeout);
        resolve(cohort);
      },
      (error) => {
        window.clearTimeout(timeout);
        reject(error);
      },
    );
  });
}

import type { ProviderDisplayInfo } from "@/shared/types/providers";

export type AgentSetupFailureKind =
  | "existing_file"
  | "unsupported_platform"
  | "unknown";

export interface AgentSetupFailureAnalysis {
  kind: AgentSetupFailureKind;
  rawOutput: string;
  existingPath?: string;
  wantedPlatform?: string;
  currentPlatform?: string;
}

export interface AgentSetupTroubleshootingRequest {
  title: string;
  prompt: string;
}

interface BuildPromptArgs {
  provider: ProviderDisplayInfo;
  analysis: AgentSetupFailureAnalysis;
  userMessage: string;
  commandError: string;
}

const NPM_PATH_PATTERN = /^npm error path\s+(.+)$/im;
const UNSUPPORTED_PLATFORM_PATTERN =
  /wanted\s+({[^)]*?})\s+\(current:\s+({[^)]*?})\)/i;

function normalizeLines(lines: Array<{ text: string }>): string {
  return lines
    .map((line) => line.text)
    .filter((line) => line.trim().length > 0)
    .join("\n");
}

function formatPlatform(value: string): string | undefined {
  try {
    const parsed = JSON.parse(value) as { os?: string; cpu?: string };
    return [parsed.os, parsed.cpu].filter(Boolean).join(" / ");
  } catch {
    return undefined;
  }
}

export function analyzeAgentSetupFailure(
  commandError: string,
  lines: Array<{ text: string }>,
): AgentSetupFailureAnalysis {
  const rawOutput = normalizeLines(lines);
  const searchable = `${commandError}\n${rawOutput}`;

  if (/npm error code EEXIST/i.test(searchable)) {
    const existingPath = searchable.match(NPM_PATH_PATTERN)?.[1]?.trim();
    return {
      kind: "existing_file",
      rawOutput,
      existingPath,
    };
  }

  if (/npm error code EBADPLATFORM/i.test(searchable)) {
    const platformMatch = searchable.match(UNSUPPORTED_PLATFORM_PATTERN);
    return {
      kind: "unsupported_platform",
      rawOutput,
      wantedPlatform: platformMatch?.[1]
        ? formatPlatform(platformMatch[1])
        : undefined,
      currentPlatform: platformMatch?.[2]
        ? formatPlatform(platformMatch[2])
        : undefined,
    };
  }

  return {
    kind: "unknown",
    rawOutput,
  };
}

export function buildAgentSetupTroubleshootingRequest({
  provider,
  analysis,
  userMessage,
  commandError,
}: BuildPromptArgs): AgentSetupTroubleshootingRequest {
  const rawOutput =
    analysis.rawOutput.trim().length > 0
      ? analysis.rawOutput.trim()
      : "No setup output was captured.";
  const contextLines = [
    `Provider id: ${provider.id}`,
    provider.binaryName ? `Expected CLI on PATH: ${provider.binaryName}` : null,
    `Berd summary: ${userMessage}`,
    `Command error: ${commandError}`,
    `Failure kind: ${analysis.kind}`,
  ].filter((line): line is string => Boolean(line));

  return {
    title: `Troubleshoot ${provider.displayName} setup`,
    prompt: [
      `I tried to set up ${provider.displayName} from Berd > AI providers, and setup failed.`,
      "",
      "Please help me troubleshoot this on my machine. First diagnose the likely cause, then inspect the relevant local npm, PATH, and CLI state, and only suggest or run a fix after explaining the tradeoff.",
      "",
      "Context:",
      ...contextLines,
      "",
      "Raw setup output:",
      "```text",
      rawOutput,
      "```",
    ].join("\n"),
  };
}

import { create } from "zustand";

import {
  clearModelSetupStatus,
  listModelSetupStatus,
  onModelSetupState,
  startModelSetup,
  type ModelSetupOperation,
  type ModelSetupPlan,
} from "@/features/providers/api/modelSetup";

// Thin, backend-backed view of model-provider native sign-in progress. Unlike
// `providerModelCacheStore` this is *not* the source of truth and is never
// persisted to localStorage — the Rust registry owns the truth. The store just
// mirrors the latest `model-setup:state` snapshot per provider so rows can be
// pure views that rehydrate instantly on (re)mount and survive a full reload.

interface ModelSetupState {
  operations: Map<string, ModelSetupOperation>;
}

interface ModelSetupActions {
  // App-level, idempotent: attach the `model-setup:state` listener and
  // rehydrate from `list_model_setup_status()`. Run once at startup (before any
  // row mounts) so reload survival works.
  init: () => Promise<void>;
  startSetup: (providerId: string, plan: ModelSetupPlan) => Promise<void>;
  getStatus: (providerId: string) => ModelSetupOperation | undefined;
  // Replace a provider's snapshot. Used by the event listener and the startup
  // rehydration.
  setOperation: (providerId: string, operation: ModelSetupOperation) => void;
  // Drop a terminal entry the row has consumed (clears the backend registry too
  // so the GC backstop has less to sweep).
  clear: (providerId: string) => void;
}

export type ModelSetupStore = ModelSetupState & ModelSetupActions;

// Module-level guard so `init` only ever attaches one listener, no matter how
// many times startup runs (StrictMode, fast re-entry).
let initialized = false;

// Per-provider revisions let `startSetup` ignore the returned seeded snapshot if
// listener-delivered progress (or a clear) landed while the invoke was in flight.
const operationVersions = new Map<string, number>();

function getOperationVersion(providerId: string): number {
  return operationVersions.get(providerId) ?? 0;
}

function bumpOperationVersion(providerId: string) {
  operationVersions.set(providerId, getOperationVersion(providerId) + 1);
}

export const useModelSetupStore = create<ModelSetupStore>((set, get) => ({
  operations: new Map(),

  init: async () => {
    if (initialized) return;
    initialized = true;

    // Attach the listener *before* the snapshot read so a transition landing
    // between the two isn't missed. The rehydration merge below preserves any
    // listener snapshot that arrives while the list request is in flight.
    await onModelSetupState((providerId, operation) => {
      get().setOperation(providerId, operation);
    });

    try {
      const entries = await listModelSetupStatus();
      set((state) => {
        const operations = new Map(state.operations);
        for (const [providerId, operation] of entries) {
          if (!operations.has(providerId)) {
            operations.set(providerId, operation);
            bumpOperationVersion(providerId);
          }
        }
        return { operations };
      });
    } catch (error) {
      console.error("Failed to rehydrate model setup status:", error);
    }
  },

  startSetup: async (providerId, plan) => {
    // Reflect the backend's seeded snapshot immediately so the spinner shows
    // when no listener event beats the command response back to the store.
    const startVersion = getOperationVersion(providerId);
    const operation = await startModelSetup(providerId, plan);
    if (getOperationVersion(providerId) !== startVersion) return;
    get().setOperation(providerId, operation);
  },

  getStatus: (providerId) => get().operations.get(providerId),

  setOperation: (providerId, operation) => {
    bumpOperationVersion(providerId);
    set((state) => {
      const operations = new Map(state.operations);
      operations.set(providerId, operation);
      return { operations };
    });
  },

  clear: (providerId) => {
    bumpOperationVersion(providerId);
    void clearModelSetupStatus(providerId).catch((error) => {
      console.error("Failed to clear model setup status:", error);
    });
    set((state) => {
      if (!state.operations.has(providerId)) return state;
      const operations = new Map(state.operations);
      operations.delete(providerId);
      return { operations };
    });
  },
}));

import { invoke } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";

import type { FixType } from "@/shared/api/doctor";

// The backend (`src-tauri/src/commands/agent_setup.rs`) is the source of truth
// for an agent provider's install / update / auth progress. The frontend only
// kicks an operation off (`startAgentSetup`), observes it (`onAgentSetupState`
// + `listAgentSetupStatus` rehydration), and clears the terminal entry it
// consumes (`clearAgentSetupStatus`). This is what lets progress survive
// navigation *and* a full window reload.

export type AgentSetupAction = "install" | "update" | "auth";

export type AgentSetupPhase =
  | "idle"
  | "checking"
  | "installing"
  | "authenticating"
  // Downloading/installing the Berd-managed Node.js runtime an npm-backed
  // fix is about to run on.
  | "preparingRuntime";

export type AgentSetupStatus = "running" | "succeeded" | "failed";

// One provider's in-flight (or just-finished) setup operation. Mirrors the
// Rust `SetupOperation` (camelCase serde); `updatedAtMs` is backend-only GC
// bookkeeping the UI ignores.
export interface AgentSetupOperation {
  action: AgentSetupAction;
  phase: AgentSetupPhase;
  status: AgentSetupStatus;
  output: string[];
  error: string | null;
}

export type AgentSetupUpdateFixType = Extract<
  FixType,
  "updateMain" | "updateBridge"
>;

// The execution recipe captured at click time. The card derives this from the
// doctor report's actionable readouts, so the backend never has to re-derive
// them while still running the chain autonomously (survives reload).
export interface AgentSetupPlan {
  // The install recipe to seed the install loop with, or null for a pure
  // update / auth.
  installFixType: Extract<FixType, "command" | "bridge"> | null;
  // Which per-readout updates to run after the install loop (`updateMain` /
  // `updateBridge`). The card names only the readout slot; the backend resolves
  // the exact source-aware command from the crate's trusted freshness readout,
  // so no renderer-supplied shell command crosses the wire.
  updateFixTypes: AgentSetupUpdateFixType[];
  // Whether the backend probes PATH after the fix to confirm the agent landed.
  // `hasBinary && !isBuiltIn`: a built-in or binary-less provider has nothing to
  // resolve on disk, so the backend skips verification and takes a clean run as
  // success (the readiness derivation that drives this stays here in the card).
  verifyInstall: boolean;
  // Whether Berd bundles this provider's ACP bridge. The bridge vendors the
  // full harness CLI, so it is the provider's only binary and reports under
  // `path`; post-fix verification then requires `path` to have resolved,
  // matching the readiness gate in `readinessFromReport` — a broken bundle
  // must fail verification instead of reporting a success the card
  // immediately contradicts as not_installed.
  bundledBridge?: boolean;
}

interface AgentSetupStateEvent {
  providerId: string;
  operation: AgentSetupOperation;
}

// Kick off (idempotently) a provider's setup operation. Returns the seeded
// snapshot; if one is already running for this provider the backend no-ops and
// returns the live snapshot.
export async function startAgentSetup(
  providerId: string,
  action: AgentSetupAction,
  plan: AgentSetupPlan,
): Promise<AgentSetupOperation> {
  return invoke("start_agent_setup", { providerId, action, plan });
}

export async function getAgentSetupStatus(
  providerId: string,
): Promise<AgentSetupOperation | null> {
  return invoke("get_agent_setup_status", { providerId });
}

// One call rehydrates every card on mount — cheaper than N `get`s when the
// providers screen mounts many cards.
export async function listAgentSetupStatus(): Promise<
  [string, AgentSetupOperation][]
> {
  return invoke("list_agent_setup_status");
}

export async function clearAgentSetupStatus(providerId: string): Promise<void> {
  return invoke("clear_agent_setup_status", { providerId });
}

// Subscribe to the single per-change snapshot event. Each event carries the
// full bounded operation, so the store replaces its view wholesale (no
// incremental merge to get wrong).
export function onAgentSetupState(
  callback: (providerId: string, operation: AgentSetupOperation) => void,
): Promise<UnlistenFn> {
  return listen<AgentSetupStateEvent>("agent-setup:state", (event) => {
    callback(event.payload.providerId, event.payload.operation);
  });
}

